import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"SymbOmni: Evolving Agentic Omni Models via Symbolic Concept Learning","description":"","frontmatter":{"title":"SymbOmni: Evolving Agentic Omni Models via Symbolic Concept Learning","arxiv":"2607.12042","date":"2026-07-13","authors":"Jinxiu Liu, Jianru Li, Tanqing Kuang, Xuanming Liu, Kangfu Mei, Yandong Wen, Weiyang Liu","categories":"cs.CV, cs.LG","topics":"智能体视频生成, 符号记忆, 持续学习","outline":[2,2]},"headers":[],"relativePath":"papers/2607.12042.md","filePath":"papers/2607.12042.md","lastUpdated":null}'),e={name:"papers/2607.12042.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="symbomni-evolving-agentic-omni-models-via-symbolic-concept-learning" tabindex="-1">SymbOmni: Evolving Agentic Omni Models via Symbolic Concept Learning <a class="header-anchor" href="#symbomni-evolving-agentic-omni-models-via-symbolic-concept-learning" aria-label="Permalink to &quot;SymbOmni: Evolving Agentic Omni Models via Symbolic Concept Learning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.12042" target="_blank" rel="noreferrer">2607.12042</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-13</td></tr><tr><td><strong>作者</strong></td><td>Jinxiu Liu, Jianru Li, Tanqing Kuang, Xuanming Liu, Kangfu Mei, Yandong Wen, Weiyang Liu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.LG（ECCV 2026）</td></tr><tr><td><strong>一句话</strong></td><td>把 ComfyUI 工作流的执行轨迹蒸馏成可检索、可组合、可用语言反馈定点修正的符号概念，让视觉生成 agent 不更新任何参数也能跨任务累积经验。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视觉生成 agent 每接一个新任务都从零规划：读文档、拼 pipeline、试错、重试，上次调通的方案下次用不上。作者称之为 <strong>perpetual novice</strong> 问题——系统缺少把经验结构化为可复用知识的机制，因此组合泛化差、知识留存低、推理开销高。企业场景尤其贵：个性化工作流无法靠通用模型覆盖，而把全部文档塞进 context 既昂贵又放大幻觉。目标是让 agent 不做任何梯度微调也能持续变强。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>统一多模态模型（GPT-Image-1、BAGEL、Janus 系列）端到端质量强，但知识只以参数形式静态存在，部署后无法累积。工作流自动化（WorkflowLLM、AFlow、ComfyAgent、ComfyGPT）能把目标翻译成可执行 DAG，但架构刚性、领域覆盖有限、存在级联错误传播。通用 agent 框架（AutoGen、ReAct、Reflexion）支持迭代精化，作者点名它们<strong>缺乏可靠的错误诊断与恢复机制</strong>：语言反馈只作用于当前 episode 的短期记忆，任务结束即丢失。要做长期符号记忆，必须先回答「什么算可复用单元、怎么检索、错了怎么删」，而这需要把工作流形式化成有语法的对象。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从既有事实出发：ComfyUI 工作流本身就是序列化成 JSON 的节点 DAG，<strong>天然是符号对象</strong>。同一批节点组合在不同任务里反复出现，这是模式不是实例。于是把成功的 DAG 抽象成带参数槽的模板、配一句描述用于语义检索，规划就从零生成 JSON 变成在文法里做推导。模板不能靠人写，只能从执行轨迹归纳；归纳需要成功与否的信号，失败时还需知道改哪一条——Reflexion 的语言反馈与 TextGrad 的文本梯度由此接入。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>先前方法把知识放错了地方：要么在参数里改不动，要么在 context 里用完即丢。SymbOmni 把知识放进一个可增删改的外部符号库，每条是「描述 + 参数化工作流模板 + 已调好的参数 + 历史效用分」。于是规划从生成解退化成组合已验证构件，学习从反向传播梯度变成用语言定位该改哪条概念。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把红车改成绿车并扩展画布」为例，循环分四相。<strong>Transduction</strong> 把指令分解为带依赖的子任务，两级级联检索——先按描述 embedding 余弦相似度召回，再按依赖约束过滤，最后按效用分排序，LLM planner（实验用 Gemini 2.5 Flash）据此实例化候选工作流。<strong>Execution</strong> 逐步调用工具并记录完整轨迹。<strong>Induction</strong> 由 Evaluation Agent 给二值判定：成功则符号化入库；失败则两个互补验证器分工，硬验证器查语法与流程正确性、软验证器查语义质量，LLM 把两者合成结构化语言损失。<strong>Memory Optimization</strong> 对比检索到的概念与实际轨迹执行 add / update / delete，失败轨迹存为负概念或参数修正。系统另打包成 ComfyUI-SymbOmni 插件，去掉原 Copilot 的闭源后端依赖。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>符号概念是四元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord mathit">Desc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathit">SWI</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathit">Params</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathit">Score</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathit">SWI</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是参数化工作流模板。全部概念构成的 Concept Box 被形式化为语言系统 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Σ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">R</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Σ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord mathit">Desc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 是语义基元词表，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord"><span class="mord mathit">SWI</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 是合法组合的产生式规则。这是最关键的形式化：<strong>规划被重述为在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span></span></span></span> 中的一次文法推导</strong>，把开放式生成压成受限搜索。检索与失败时的更新分别为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ret</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord mathrm">Rank</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∘</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Filter</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">struct</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∘</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Retrieve</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sem</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">CB</span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">CB</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">Refine</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathrm">CB</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">Replay</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sym</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">sym</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是「符号梯度」，由链式归因定位到该修改的条目。需说清楚：这里没有任何真实微分，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">∇</span></span></span></span> 只是类比记号，可靠性完全由 LLM 的归因能力决定而非由数学性质保证。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>符号记忆能否提高成功率？</strong> ComfyBench（200 任务）上 100% pass、86.0% 总 resolve；complex 从 75.0% 升到 83.3%，creative 从 42.5% 升到 67.5%。相同工具配置下换 Nano Banana 后 91.0% vs ComfyMind 84.0%——这条对照关键，它把增益归给概念学习而非底层生成模型。正文声称 GenEval overall 0.98（ComfyMind 0.90、GPT-Image-1 0.84），ReasonEdit 9.190 vs 8.135；需注意 HTML 版表 2 的数值排布与正文不一致，此处以正文为准。</p><p><strong>记忆是省钱还是费钱？</strong> 去掉记忆检索后，ReasonEdit 上总 token 从 14,361 涨到 21,727（+33.9%），每例 API 请求从 7.25 涨到 9.85。</p><p><strong>学到的是模式还是实例？</strong> 用 147 个社区野生工作流单独建库并完全替换原库，ComfyBench 总 resolve 从 67.0% 升到 75.0%；offline 模式不给任何文档仅靠积累的概念，在 complex 分片上 70.0% 超过有完整文档的 ComfyMind 的 66.7%。另有 63 人 1,197 次盲测，对 Nano Banana 偏好率 59.2%、对 ComfyMind 65.9%。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视觉生成 agent 的真问题不是单次质量而是经验无法累积。SymbOmni 把成功轨迹抽象成带参数槽的符号工作流指令存入可编辑的 Concept Box。规划因此从生成退化为文法推导，失败时用语言反馈定位到具体概念修正。全程不更新参数，却把 creative 任务 resolve rate 从 42.5% 提到 67.5%，同时省掉三分之一 token。概念能跨分布迁移：野生工作流学到的概念迁到 benchmark 仍有 +8.0 增益。</p><p><strong>3 句话版</strong>：把经验形式化为「描述 + 模板 + 参数 + 效用分」的符号概念，用归纳-演绎循环持续扩充。规划变成组合已验证构件，失败由双验证器诊断并做符号级修正。不改参数即可持续学习且省 token。</p><p><strong>1 句话版</strong>：用可增删改的外部符号工作流库替代参数微调，实现视觉生成 agent 的持续学习。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>整个循环的<strong>唯一学习信号来自 Evaluation Agent 的二值判定</strong>。它不成立的代价是灾难性的：错误的成功判定会把坏工作流写进 CB，而 CB 又会被检索复用，错误被放大而非稀释。论文在附录 0.H 承认了记忆污染风险，应对是 add/update/delete 与 verbalized backpropagation，但这是<strong>机制性论证而非实证证据</strong>：全文未报告 judge 与人工标注的一致率，也没做「注入错误概念看能否自愈」的对照。附录 0.G 的一个数字值得警惕——基线检索得分只有 2.9/5.0，合并多域概念后才升到 3.3/5.0，说明喂给 planner 的概念平均质量并不高。此外官方评测同样由 LLM judge 完成，优化目标与评价指标共享同一类判别器，这一自洽性风险论文未讨论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内的最小验证不需要整个系统：取 ComfyBench 的 60 个 complex 任务，实现只有「描述 + 模板 + 参数」三元组的极简概念库；用任意 LLM 做 planner，只实现 Transduction 与「成功即入库」的最简 Induction，不实现语言反馈；对照组禁用检索；测量 resolve rate、每例 token 与尝试次数，按任务顺序画学习曲线。<strong>判定标准</strong>：若开启记忆后 resolve 提升且 token 单调下降，说明符号复用本身就是主要增益来源；若两组曲线重合，则增益更可能来自失败诊断而非记忆检索。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给出<strong>替代解释</strong>：增益可能主要来自 prompt 里多了几个高质量 in-context 示例，与「符号」「持续学习」无关。对照是构造静态基线——把演化结束后的 CB 冻结、去掉全部归纳与增删改逻辑、仅保留检索与实例化，作为纯 RAG 系统评测；若它与完整 SymbOmni 接近，自演化这一核心卖点就没被实验支撑。</p><p>第二个攻击面是<strong>可预测的失败条件</strong>：检索基于描述 embedding 相似度，当两个任务描述相近但所需结构截然不同时（如「移除物体」与「移除物体后补全背景纹理」），系统会稳定召回错误概念且因效用分高被排在前面。构造 20 个近义歧义对，预测表现会<strong>低于</strong>无记忆基线，即负迁移；论文未报告任何负迁移案例。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：概念库只增不减地长，靠 LLM 自己判断该删谁，把知识库的健康托付给一个没有校准的判别器。</p><p><strong>新 framing</strong>：把 Concept Box 当作需要被<strong>主动实验验证</strong>的科学假设集合而非被动经验日志。可借鉴主动学习与 bandit：每条概念带后验分布而非标量效用分，系统在低置信度概念上主动安排探针任务，把检索从 exploit-only 变成 explore-exploit。这改变的是知识的认识论地位——从记录变成可证伪假设。</p><p><strong>第一个实验</strong>：给每条概念维护 Beta 后验、用 Thompson sampling 选概念，每完成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个任务挑后验方差最大的概念合成最小任务去测量，对照贪心 Rank。核心观测量不是最终 resolve rate，而是<strong>概念效用估计的校准误差</strong>随任务数的下降速度，以及注入 10 个人工坏概念后两者的清除时间。</p>',36)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
